package com.openggf.game.soniccd.player;
import com.openggf.game.soniccd.objects.*;
import java.util.*;import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
/** Tests FIRST. Constructed primitive owner; no real World/native/capture admission. */
class TestCdPlayerTimeWarpOriginalOperations {
 @Test void fastStarCreationUsesOneSharedKernelAndElevenNativeSites(){var h=new Host();var before=h.bank.capture();var pure=CdPlayerTimeWarp.step(h.input(),new CdPlayerTimeWarp.Context(OptionalInt.of(1),Optional.of(before)));var actual=h.run();assertEquals(pure,actual);assertEquals(1,h.timer);assertEquals(1,h.warp);assertEquals(1,h.reads);assertEquals(10,h.writes.size());for(int w=12;w<=15;w++){assertEquals(3,h.bank.state(w).byteAt(0));assertEquals(w-7,h.bank.state(w).byteAt(0x1C));for(int b=0;b<64;b++)if(b!=0&&b!=0x1C)assertEquals(before.slots().get(w-1).byteAt(b),h.bank.state(w).byteAt(b));}}
 @Test void directionZeroAndChargeDoNotTouchTheReservedOwner(){for(int charge:new int[]{0,1}){var h=new Host();h.direction=0;h.charge=charge;h.run();assertEquals(0,h.reads);assertTrue(h.writes.isEmpty());}}
 @Test void reservedReadFailureKeepsEarlierTimerStoreAndOriginalThrowable(){var h=new Host();h.readFault=new Fault();assertSame(h.readFault,assertThrows(Fault.class,h::run));assertEquals(1,h.timer);assertEquals(0,h.warp);assertEquals(0,h.bank.state(12).byteAt(0));assertEquals(0,h.readFault.getSuppressed().length);}
 @Test void refusedSecondStarAnimationRetainsEveryEarlierStoreAndDirtyByte(){var h=new Host();h.refuseWhole=13;h.refuseAnimation=true;var fault=h.storeFault=new Fault();var old=h.bank.state(13);assertSame(fault,assertThrows(Fault.class,h::run));assertEquals(1,h.warp);assertEquals(3,h.bank.state(12).byteAt(0));assertEquals(5,h.bank.state(12).byteAt(0x1C));assertEquals(3,h.bank.state(13).byteAt(0));assertEquals(old.byteAt(0x1C),h.bank.state(13).byteAt(0x1C));assertEquals(0,h.bank.state(14).byteAt(0));assertEquals(0,fault.getSuppressed().length);}
 @Test void landedStoreFaultRetainsNativeByteAndExpiresReceipt(){var h=new Host();h.refuseWhole=12;h.refuseAnimation=false;h.afterLanded=true;var fault=h.storeFault=new Fault();assertSame(fault,assertThrows(Fault.class,h::run));assertEquals(3,h.bank.state(12).byteAt(0));assertThrows(IllegalStateException.class,()->h.saved.requireCurrent(h));assertEquals(0,fault.getSuppressed().length);}
 @Test void foreignOffThreadAndRetiredCallsCannotAuthorizePrimitiveUse(){var h=new Host();h.before=()->{var c=h.saved;assertThrows(IllegalStateException.class,()->c.requireCurrent(new Host()));var x=new AtomicReference<Throwable>();var t=new Thread(()->{try{c.requireCurrent(h);}catch(Throwable f){x.set(f);}});t.start();try{t.join();}catch(InterruptedException e){throw new AssertionError(e);}assertInstanceOf(IllegalStateException.class,x.get());};h.run();assertThrows(IllegalStateException.class,()->h.saved.requireCurrent(h));}
 @Test void slowPathKeepsSameNativeGlobalOrderWithoutReservedRead(){var h=new Host();h.speed=0x5ff;h.run();assertEquals(0,h.timer);assertEquals(0,h.warp);assertEquals(1,h.direction);assertEquals(List.of("TIMER_WORD:1","TIMER_WORD:0","TIME_WARP_BYTE:0"),h.writes);assertEquals(0,h.reads);}
 @Test void occupiedFirstStarReturnsWithoutOverwritingAnyStar(){var h=new Host();h.bank.write(h.bank.state(12).moveByteAt(0,9));var before=h.bank.capture();h.run();assertEquals(before.slots(),h.bank.capture().slots());assertEquals(1,h.timer);assertEquals(0,h.warp);assertEquals(1,h.reads);}
 static final class Fault extends RuntimeException{ }
 static final class Host implements CdPlayerTimeWarp.OriginalOwner {
  com.openggf.game.soniccd.level.CdAssetBytes raw=com.openggf.game.soniccd.level.CdAssetBytes.copyOf(new byte[31*64]);final CdReservedObjectBank bank=CdReservedObjectBank.backedBy(new CdReservedObjectBank.RawBacking(){public com.openggf.game.soniccd.level.CdAssetBytes read(){return raw;}public boolean compareAndSet(com.openggf.game.soniccd.level.CdAssetBytes before,com.openggf.game.soniccd.level.CdAssetBytes next){if(!Arrays.equals(raw.copy(),before.copy()))return false;raw=next;return true;}});final List<String>writes=new ArrayList<>();int timer,direction=1,warp,speed=0x600,charge,reads,refuseWhole=-1;boolean refuseAnimation,afterLanded;Fault readFault,storeFault;CdPlayerTimeWarp.OriginalCall saved;Runnable before=()->{};
  Host(){for(int w=1;w<32;w++){var b=new byte[64];Arrays.fill(b,(byte)(w+19));b[0]=0;bank.write(bank.state(w).withBytes(b));}}
  CdPlayerTimeWarp.Input input(){return new CdPlayerTimeWarp.Input(0,1,0x164c,charge,speed,direction,timer,warp);}
  CdPlayerTimeWarp.Result run(){return CdPlayerTimeWarp.stepOriginal(input(),new CdPlayerTimeWarp.Context(OptionalInt.of(1),Optional.empty()),this);}
  public void before(CdPlayerTimeWarp.OriginalCall c){c.requireCurrent(this);saved=c;before.run();}
  public CdReservedObjectBank.Snapshot reserved(CdPlayerTimeWarp.OriginalCall c){c.requirePrimitive(this);reads++;if(readFault!=null)throw readFault;return bank.capture();}
  public void store(CdPlayerTimeWarp.OriginalCall c){c.requirePrimitive(this);var s=c.store();if(s instanceof CdPlayerTimeWarp.GlobalWrite g){writes.add(g.field()+":"+g.value());switch(g.field()){case TIMER_WORD->{assertEquals(timer,g.expectedValue());timer=g.value();}case DIRECTION_BYTE->{assertEquals(direction,g.expectedValue());direction=g.value();}case TIME_WARP_BYTE->{assertEquals(warp,g.expectedValue());warp=g.value();}}}else{var w=(CdPlayerTimeWarp.ReservedWrite)s;boolean fail=w.wholeIndex()==refuseWhole&&(w.field()==CdPlayerTimeWarp.ReservedField.ANIMATION)==refuseAnimation;if(fail&&!afterLanded)throw storeFault;var at=w.field()==CdPlayerTimeWarp.ReservedField.ID?0:0x1C;var old=bank.state(w.wholeIndex());assertEquals(w.expectedValue(),old.byteAt(at));bank.write(old.moveByteAt(at,w.value()));writes.add(w.wholeIndex()+":"+w.field());if(fail)throw storeFault;}}
  public void after(CdPlayerTimeWarp.OriginalCall c){c.requireCurrent(this);}
  public void failed(CdPlayerTimeWarp.OriginalCall c,Throwable original){c.requireCurrent(this);}
 }
}
